USE ROLE USERADMIN;

CREATE USER IF NOT EXISTS BANKING_PIPELINE_SERVICE_USER
    TYPE = SERVICE
    DEFAULT_ROLE = BANKING_PIPELINE_SERVICE_ROLE
    DEFAULT_WAREHOUSE = WAREHOUSE_FOR_LOADING_AND_TRANSFORMING
    RSA_PUBLIC_KEY = ''
    COMMENT = 'Service user for dbt and Airflow. Signs in with a key pair only. Uses the pipeline role.';

GRANT ROLE BANKING_PIPELINE_SERVICE_ROLE TO USER BANKING_PIPELINE_SERVICE_USER;

DESC USER BANKING_PIPELINE_SERVICE_USER;